// Direct content generation for Section 2 using actual company data
const companyData = $input.first().json;

console.log('=== DIRECT SECTION 2 GENERATION ===');
console.log(`Company: ${companyData.company_name}`);
console.log(`Company ID: ${companyData.company_id}`);
console.log(`Content length: ${companyData.content?.length || 0} characters`);

if (!companyData.content || companyData.content.length < 100) {
  console.log('❌ Insufficient company data for generation');
  return [{
    json: {
      error: 'Insufficient company data',
      company_id: companyData.company_id,
      company_name: companyData.company_name
    }
  }];
}

// Extract key information from company content
const content = companyData.content || '';
const companyName = companyData.company_name || 'the Company';

// Determine jurisdiction from company content
let jurisdiction = 'Delaware, United States';
if (content.toLowerCase().includes('united kingdom') || content.toLowerCase().includes('england') || content.toLowerCase().includes('wales')) {
  jurisdiction = 'England and Wales';
} else if (content.toLowerCase().includes('canada') || content.toLowerCase().includes('ontario') || content.toLowerCase().includes('toronto')) {
  jurisdiction = 'Ontario, Canada';
} else if (content.toLowerCase().includes('australia') || content.toLowerCase().includes('sydney') || content.toLowerCase().includes('melbourne')) {
  jurisdiction = 'New South Wales, Australia';
} else if (content.toLowerCase().includes('singapore')) {
  jurisdiction = 'Singapore';
} else if (content.toLowerCase().includes('delaware') || content.toLowerCase().includes('incorporated') || content.toLowerCase().includes('corp') || content.toLowerCase().includes('inc')) {
  jurisdiction = 'Delaware, United States';
}

// Extract latest filing date from content
let latestFilingDate = new Date().toISOString().split('T')[0];
const datePattern = /\d{4}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/\d{4}|\d{1,2} [A-Za-z]+ \d{4}/g;
const dates = content.match(datePattern);
if (dates && dates.length > 0) {
  // Use the most recent date found
  latestFilingDate = dates[dates.length - 1];
}

// Generate Section 2 content with actual company data
const section2Content = `**Section 2: Legal Disclaimers & Reliance Limitations**

**Intended Use and Reliance Restriction**

This commercial due diligence report is prepared solely for Action Labs' client in connection with evaluating a potential transaction involving ${companyName}. No third party may rely on this report for any purpose. Action Labs disclaims all liability to any party other than the client, whether in contract, tort, or otherwise.

**Engagement Scope and Basis of Preparation**

This report is based solely on publicly available information concerning ${companyName}. No access was granted to confidential information, management interviews, internal forecasts, or non-public data, unless specifically stated elsewhere in this report. Public information may be incomplete, redacted, or unaudited, and has not been independently verified by Action Labs.

**Report Scope Boundaries**

This is a commercial due diligence report only concerning ${companyName}. Action Labs disclaims responsibility for legal, tax, regulatory, HR, cybersecurity, audit, valuation, or technical due diligence. This report does not constitute financial forecasts, legal advice, or investment recommendations regarding ${companyName}.

**Forward-Looking Disclosure Caveat**

Forward-looking statements made by ${companyName} in public disclosures are included solely for reference and are not endorsed or assured by Action Labs. No opinion is expressed on the likelihood of their realization.

**Liability Limitation and Indemnity**

Action Labs makes no representation or warranty as to the completeness, accuracy, or fitness for purpose of the information reviewed concerning ${companyName}. Our liability is limited to our client and subject to the terms of our engagement letter.

**Update and Revision Disclaimer**

This report is based on public disclosures concerning ${companyName} as of ${latestFilingDate}. Action Labs undertakes no duty to update, revise, or supplement this report in light of subsequent events or filings.

**Legal Jurisdiction Clause**

This report and the disclaimers herein shall be governed by and interpreted in accordance with the laws of ${jurisdiction} unless otherwise stated in the governing engagement documents.

**Draft Status**

This document is a working draft and should not be interpreted as a final opinion unless explicitly marked as such by Action Labs.

**References to Appendices**

For validation purposes, this report references:
- Appendix A: Management Interview Script
- Appendix B: Due Diligence RFI List

Prepared by Action Labs - Commercial Strategy & Due Diligence`;

console.log(`✅ Generated Section 2 content for ${companyName}`);
console.log(`Content length: ${section2Content.length} characters`);
console.log(`Jurisdiction identified: ${jurisdiction}`);
console.log(`Latest filing date: ${latestFilingDate}`);

return [{
  json: {
    company_id: companyData.company_id,
    company_name: companyData.company_name,
    output: section2Content,
    content_length: section2Content.length,
    generation_method: 'direct_company_specific',
    jurisdiction: jurisdiction,
    latest_filing_date: latestFilingDate,
    status: 'section2_complete'
  }
}];

