// Process the retrieved company data for AI agent
const companyRecords = $input.all();

console.log('=== RETRIEVING COMPANY DATA FOR SECTION 2 ===');
console.log(`Found ${companyRecords.length} company records in database`);

if (companyRecords.length === 0) {
  console.log('❌ No company data found in database');
  return {
    json: {
      error: 'No company data available for Section 2 generation',
      message: 'Please ensure the main workflow has processed company PDFs first'
    }
  };
}

// Get the most recent company data
const latestCompany = companyRecords[0]?.json || {};

console.log(`Processing company: ${latestCompany.company_name}`);
console.log(`Company ID: ${latestCompany.company_id}`);
console.log(`Content length: ${latestCompany.content?.length || 0} characters`);
console.log(`Processed at: ${latestCompany.processed_at}`);

// Prepare comprehensive company data for AI agent
const companyData = {
  company_id: latestCompany.company_id,
  company_name: latestCompany.company_name,
  folder_id: latestCompany.folder_id,
  content: latestCompany.content || '',
  processed_at: latestCompany.processed_at,
  content_summary: {
    total_length: latestCompany.content?.length || 0,
    has_content: !!(latestCompany.content && latestCompany.content.length > 100)
  }
};

console.log(`✅ Prepared company data for Section 2 generation`);
console.log(`Company: ${companyData.company_name}`);
console.log(`Content available: ${companyData.content_summary.has_content}`);

return {
  json: companyData
};
